#include "matmul_lyc_custom_host.h"

#include <stdexcept>
#include <string>

#include "matmul_lyc_custom_tiling.h"

// Host stub generated by the AscendC compiler for the device kernel.
extern "C" void matmul_lyc_custom(
    uint32_t blockDim, void *l2Ctrl, aclrtStream stream,
    uint8_t *a, uint8_t *b, uint8_t *c,
    uint32_t nTiles, uint32_t baseN, uint32_t baseK, uint32_t l1K,
    uint32_t kL1Tiles, uint32_t l1Prefetch);

namespace ascend_kernel {

void LaunchMatmulLycCustom(
    uint32_t m, uint32_t k, uint32_t n, int32_t deviceId,
    aclrtStream stream, uint8_t *a, uint8_t *b, uint8_t *c)
{
    int64_t availableCoreNum = 0;
    const aclError status = aclrtGetDeviceInfo(
        deviceId, ACL_DEV_ATTR_CUBE_CORE_NUM, &availableCoreNum);
    if (status != ACL_SUCCESS) {
        throw std::runtime_error(
            "aclrtGetDeviceInfo(CUBE_CORE_NUM) failed: " + std::to_string(status));
    }
    if (availableCoreNum <= 0) {
        throw std::runtime_error("the device reports no available Cube cores");
    }

    const MatmulLycCustomTiling tiling = ComputeMatmulLycCustomTiling(
        m, k, n, static_cast<uint32_t>(availableCoreNum));
    matmul_lyc_custom(
        tiling.blockNum, nullptr, stream, a, b, c,
        tiling.nTiles, tiling.baseN, tiling.baseK, tiling.l1K,
        tiling.kL1Tiles, tiling.l1Prefetch);
}

} // namespace ascend_kernel
